narrative:
## Telling the User What Went Wrong

A good error message answers three questions: what went wrong, why, and what to do about it.

### Custom Error Messages

```xiom
fn validate_username(name: Str) -> Result[Str, Str] {
  if string.str_length(name) < 3 {
    return Err("Username must be at least 3 characters");
  }
  if string.str_length(name) > 20 {
    return Err("Username must be 20 characters or fewer");
  }
  return Ok(name);
}

fn main() -> Int {
  match validate_username("ab") {
    Ok(name) => io.println("Welcome, " + name + "!"),
    Err(e) => io.println(e),
  };
  match validate_username("a_very_long_username_indeed") {
    Ok(name) => io.println("Welcome, " + name + "!"),
    Err(e) => io.println(e),
  };
  return 0;
}
```

### Validating Multiple Fields

```xiom
fn process_registration(age_str: Str, name: Str) -> Result[Str, Str] {
  let age = string.str_to_int(age_str)?;

  if age < 0 {
    return Err("Age cannot be negative!");
  }
  if age < 13 {
    return Err("You must be at least 13 years old");
  }
  if age > 120 {
    return Err("Please enter a valid age");
  }
  if string.str_length(name) == 0 {
    return Err("Name cannot be empty");
  }

  return Ok("Registered " + name + ", age " + string.int_to_str(age));
}

fn main() -> Int {
  let r1 = process_registration("25", "Alice");
  let r2 = process_registration("10", "Bob");
  let r3 = process_registration("-5", "");

  io.println(r1.unwrap_or("Failed"));
  io.println(r2.unwrap_or("Failed"));
  io.println(r3.unwrap_or("Failed"));
  return 0;
}
```

### Building Error Messages Dynamically

```xiom
fn check_quantity(qty_str: Str, max: Int) -> Result[Int, Str] {
  let qty = string.str_to_int(qty_str)?;
  if qty < 1 {
    return Err("Quantity must be at least 1, got " + string.int_to_str(qty));
  }
  if qty > max {
    return Err("Only " + string.int_to_str(max) + " items available");
  }
  return Ok(qty);
}
```

