use xiom.io;

use xiom.string;
fn validate_password(pw: Str) -> Result[Str, Str] {
  let len = string.str_length(pw);
  if len < 8 { return Err("Password must be at least 8 characters"); }
  if len > 30 { return Err("Password must be 30 characters or fewer"); }
  if pw == "password" { return Err("Password cannot be 'password' — too easy to guess!"); }
  return Ok(pw);
}

fn validate_email(email: Str) -> Result[Str, Str] {
  if string.str_length(email) == 0 { return Err("Email cannot be empty"); }
  let has_at = false;
  let at_pos = 0;
  let i = 0;
  while i < string.str_length(email) {
    if string.str_slice(email, i, i + 1) == "@" { has_at = true; at_pos = i; }
    i = i + 1;
  }
  if !has_at { return Err("Email must contain @"); }
  let has_dot = false;
  let j = at_pos;
  while j < string.str_length(email) {
    if string.str_slice(email, j, j + 1) == "." { has_dot = true; }
    j = j + 1;
  }
  if !has_dot { return Err("Email must have a dot after the @"); }
  return Ok(email);
}

fn main() -> Int {
  io.println(validate_password("abc").unwrap_or("Failed").to_str());
  io.println(validate_password("a_very_long_password_that_exceeds_thirty_chars").unwrap_or("Failed").to_str());
  io.println(validate_password("secure123").unwrap_or("Failed").to_str());
  io.println(validate_email("").unwrap_or("Failed").to_str());
  io.println(validate_email("no_at_sign").unwrap_or("Failed").to_str());
  io.println(validate_email("user@site").unwrap_or("Failed").to_str());
  io.println(validate_email("user@site.com").unwrap_or("Failed").to_str());
  return 0;
}
